package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.*;

/**
 * JUnit 5 tests for TypeHandler#createDefaultMap() and related behavior.
 */
public class TypeHandler_createDefaultMap_2_0_Test_testTypeHandlerConstructorNullThrowsNPE {

    @Test
    public void testTypeHandlerConstructorNullThrowsNPE() {
        // Ensure passing null to the Map-based constructor throws NPE
        assertThrows(NullPointerException.class,
                () -> new TypeHandler((Map<Class<?>, Converter<?, ? extends Throwable>>) null));
    }

    @Test
    public void testCreateDefaultMapNotEmptyAndContainsCommonTypes() {
        Map<Class<?>, Converter<?, ? extends Throwable>> map = TypeHandler.createDefaultMap();
        assertNotNull(map, "createDefaultMap must not return null");
        assertFalse(map.isEmpty(), "createDefaultMap should not return an empty map");

        // Every entry should have non-null key and non-null value
        for (Map.Entry<Class<?>, Converter<?, ? extends Throwable>> e : map.entrySet()) {
            assertNotNull(e.getKey(), "Map key should not be null");
            assertNotNull(e.getValue(), "Map value should not be null");
        }

        // Check presence of commonly expected types conservatively.
        // For each semantic group we accept several alternatives (wrapper, primitive, or common supertypes).
        assertTrue(hasAnyKey(map.keySet(), String.class, CharSequence.class),
                "Expected a converter for some string/char-sequence type (e.g. String)");

        assertTrue(hasAnyKey(map.keySet(), Integer.class, int.class, Number.class),
                "Expected a converter for some integer/number type (e.g. Integer or int)");

        assertTrue(hasAnyKey(map.keySet(), Long.class, long.class, Number.class),
                "Expected a converter for some long/number type (e.g. Long or long)");

        assertTrue(hasAnyKey(map.keySet(), Boolean.class, boolean.class),
                "Expected a converter for some boolean/primitive-boolean type (e.g. Boolean)");
    }

    @Test
    public void testCreateDefaultMapReturnsIndependentMapsWithSameKeys() {
        Map<Class<?>, Converter<?, ? extends Throwable>> m1 = TypeHandler.createDefaultMap();
        Map<Class<?>, Converter<?, ? extends Throwable>> m2 = TypeHandler.createDefaultMap();

        // Should be separate map instances
        assertNotSame(m1, m2);

        // Keys should be the same between invocations (structure expected to be identical)
        assertEquals(m1.keySet(), m2.keySet(), "createDefaultMap should produce same set of keys on repeated calls");

        // Mutating a copy made from the original should not affect the original map.
        // Choose an existing key from m1 to remove from the copy.
        assertFalse(m1.isEmpty(), "m1 must not be empty for this test");
        Class<?> keyToRemove = m1.keySet().iterator().next();
        assertTrue(m1.containsKey(keyToRemove), "Sanity: original map should contain the selected key");

        Map<Class<?>, Converter<?, ? extends Throwable>> copy = new HashMap<>(m1);
        copy.remove(keyToRemove);

        // Original must still contain the key (independence)
        assertTrue(m1.containsKey(keyToRemove), "Original map should not be affected by changes to the copy");
    }

    // Helper: returns true if any candidate class is present in the key set.
    private static boolean hasAnyKey(Set<Class<?>> keys, Class<?>... candidates) {
        for (Class<?> c : candidates) {
            if (keys.contains(c)) {
                return true;
            }
        }
        return false;
    }
}
